-- Splynn Dimensional Market: the last 11 of the book's 19 Bio-Wizard parasites, Locater to Temporal Link, printed 119-127.
-- 11 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~359-splynn-parasites-b.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('locater', 'Locater (Parasite)', 'rifts', 'magic', NULL, 250000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A pea-sized slave-tracking organism, bred sterile by Bio-Wizards, lodged anywhere in the skull or spine of a mortal host (humans, D-Bees and the like; never supernatural beings or creatures of magic). 1D6 Hit Points, lives up to twenty years, non-sentient. It gives the host nothing; instead it sends out a psionic signal that only the one person named by the implanting Bio-Wizard can feel, out to 20 miles (32 km). That owner or slave master is +40% to track the host and knows roughly how far off and where he is while inside that range. No bonuses. Surgery leaves no harm unless the roll fails; a botched one sends him to the Surgery Penalty Table (body implants), Rifts Atlantis p.114. It pays no attention to other organisms.', 'Rifts World Book 21: Splynn Dimensional Market p.119', NULL),
  ('lunglock', 'LungLock (Parasite)', 'rifts', 'magic', NULL, 150000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A slave-control pair, one flat dark-blue organism 3 inches (76 mm) long and 1 inch (25 mm) wide in each lung of a mortal host (never supernatural beings or creatures of magic); 1D6+1 Hit Points, 2D6-year life span, low animal intelligence. The pair breed one young a year, coughed out through the mouth, which must find a mate and a host inside 48 hours or die. No powers or bonuses: it eats the host''s air. Endurance is halved, and after 1D4+1 minutes of running, swimming, combat or other hard exertion, or under great stress or terror, he has an asthma-like fit: one melee action or attack, no initiative, every combat bonus at zero, Spd -95% and skills -60%. Recovery takes 2D4 minutes of full rest; if he spends his one action on anything but resting, the fit and its penalties go on. An owner keeps it in check with the Aerobe micro-organism, which restores him within one melee round, though without bonuses. Surgery does no lasting harm unless the roll fails; then roll on the Surgery Penalty Table, Rifts Atlantis p.114. It ignores other organisms.', 'Rifts World Book 21: Splynn Dimensional Market p.119-120', NULL),
  ('magic-booster', 'Magic Booster (Parasite)', 'rifts', 'magic', NULL, 500000, '500,000 credits; popular with low-level mages, scorned by archmages', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A fat caterpillar-like organism about 5 inches (127 mm) long set at the base of the neck or on the spine of a human or D-Bee (never supernatural creatures or creatures of magic). 10 Hit Points, eight-month life, low animal intelligence. Boosters mate before bonding: the males die at once, and a bonded female carries young for eight months, then dies giving birth to 1D6. The host gains 1D4x10+12 P.P.E. and +2 to save vs magic, and a practitioner of magic +1 to spell strength. While bonded he is sluggish: -2 initiative and -10% to skills. When it dies or is removed its P.P.E. and bonuses leave with it, and the sluggishness lingers another 2D6 weeks. P.P.E. comes back at half the normal rate, and every spell he casts spends its normal P.P.E. and then rolls percentile: 01-20%, damage or duration 20% above normal; 21-40%, 20% below; 41-60%, 50% above; 61-80%, 50% below; 81-100%, the spell works normally but a backlash deals 1D6 M.D. to the caster and everyone within 10 ft (3 m) of him. Surgery may leave slight scarring and nothing worse. Killing it scars the bonding site (-1 P.B.) and its death throes drain 1D6x10 P.P.E. from the host, regained normally. Magic cannot touch it, Restoration included. Only one may be worn at a time; it tolerates other organisms.', 'Rifts World Book 21: Splynn Dimensional Market p.120-121', NULL),
  ('mend-and-melt', 'Mend & Melt (Parasite)', 'rifts', 'magic', NULL, 350000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A microscopic swarm that in the wild clings under leaves to be eaten by grazers; in the bloodstream of an S.D.C. host (never supernatural beings, creatures of magic or M.D.C. beings) it does the work of the white blood cells. 1D4 Hit Points, 1D6-month life span, no discernible intelligence. The host regenerates 1D6 Hit Points and S.D.C. every melee round, survives damage down to -75 Hit Points unless the brain is destroyed, and regrows severed limbs, lost organs and nearly any other harm inside 72 hours if the brain is largely whole; heavy brain damage heals too, at a possible cost of 1D4 I.Q. (G.M.''s call). He is effectively immune to poison, toxins, drugs and disease, and toxic gases and magic potions do half damage for half the duration. 1D6 months in, the swarm divides into 1D4 new collectives: healing stops, and to breed it strips protein from the host, whose flesh partly melts away, a permanent loss of half his Hit Points and three quarters of his S.D.C., P.S. and P.E. -3 each, P.B. -70%, -4 to save vs poison, toxins, drugs and disease, and wounds healing at half speed. Surgery cannot remove it. Purge Self or Purge Others clears it only before it breeds; Restoration returns the host to his former health except P.B., which stays 20% lower. It ignores other organisms, and the melting does not harm them.', 'Rifts World Book 21: Splynn Dimensional Market p.121-122', NULL),
  ('mind-blossom', 'Mind-Blossom (Parasite)', 'rifts', 'magic', NULL, 350000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Also called Algernon''s Flower: a sterile Bio-Wizard mutant of a spore-bearing alien plant, injected into the blood or planted at the base of the skull (rarely breathed in), that roots in the brain of an S.D.C. host (never supernatural beings, creatures of magic or M.D.C. beings). A grain of sand at first, about 4 inches (101 mm) grown; 1D4 Hit Points, lives 3D6+6 months, non-sentient. 1D4 days in, I.Q. rises a point a day for 2D4 days, and a psychic also gains 1D6 I.S.P. on each of those days. After 1D4 months it is mature: +10% to all skills and +2 M.E., and a psychic gets another 2D6 I.S.P. and +1 to save vs psionics; a scholarly mage (Ley Line Walker, Shifter and the like) also works out 1D4+1 new spells by then, none above his own level. When it dies the I.Q., M.E., skill and I.S.P. gains vanish and the rotting husk eats at the brain: 1D4 days on, the host loses 1 I.Q. a week for 2D4 weeks (2-8 points). Below his O.C.C. requirement he needs double the experience to level; at half his I.Q. or less, skills are -30% and he is forgetful and distracted; a mage can cast only one spell per melee and no rituals; a psychic loses 1D6 I.S.P. a week over the same span, and at zero or below loses every power for good, even ones needing no I.S.P. At I.Q. 3-4 he keeps a seven-year-old''s wits and only a few favourite spells or powers; at 2 or less he is a vegetable beyond recovery. Surgery may damage the brain (Surgery Penalty Table for the brain, Rifts Atlantis p.114); surgery soon after it dies, before those 1D4 days are out, is harmless, and damage once it has died and rotted is permanent. It tolerates other organisms, but the Mind Helmet (so printed) kills it at once and the Brain Feeder eats the spore before it sprouts; a Brain Feeder added to an infected host gives no I.S.P. and devours the brain and the Mind-Blossom alike.', 'Rifts World Book 21: Splynn Dimensional Market p.122-123', NULL),
  ('muscle-boots', 'Muscle Boots (Parasite)', 'rifts', 'magic', NULL, 150000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A pale green, jellyfish-like grassland creature that grips the leg of whatever steps on it, moulds itself to the foot and shin and hardens into tough leathery hide, the size of a thick human boot. S.D.C. hosts only (never supernatural beings, creatures of magic or M.D.C. beings). 6D6 Hit Points, lives 1D4+1 years, low animal intelligence. It mates before taking a host and carries 2D6 eggs in a pouch for 1D4 years, then releases them, drops off and soon dies. Each one strengthens one leg: a kick does 2D6 M.D., a leap kick double that, and a leap carries up to 20 ft (6 m) up or forward; with a pair, leap distance doubles and so does running speed. +2 to strike with kicks, +1 with a leap kick. It is clumsy, -15% to Prowl, and must sleep five unbroken hours a day, matching the host''s sleep; woken abruptly, the host finds it still asleep: no powers or bonuses, Spd and natural leaping halved, no prowling and -20% to most other physical skills. Surgery or killing it removes it harmlessly. It ignores other organisms.', 'Rifts World Book 21: Splynn Dimensional Market p.123', NULL),
  ('para-sym-transformer', 'Para-Sym Transformer (Parasite)', 'rifts', 'magic', 50, 1800000, '1.8 to 2.5 million credits, by availability and the buyer''s desperation; rare', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A tough round body the size of a human chest, about 50 lbs (22.5 kg), with eight long tendrils that bore into the host''s chest and ribs: minutes of agony, then power beyond a Juicer''s, and death 48 hours later. S.D.C. hosts only (never supernatural beings, creatures of magic or M.D.C. beings). A Mega-Damage creature of 1D6x10 M.D.C., low animal intelligence; unbonded it lives up to a month past maturity. For 48 hours the host gains 5D6x10 M.D.C. and +4 P.E. and needs no rest or sleep; regenerates 2D6 M.D.C. per minute; poison, toxins, drugs and disease cannot touch him; +3D6 P.S. (30 at least), counted supernatural; +2D6x10 Spd and leaps 20 ft (6.1 m) farther up and across; +2D6 P.P. (22 at least), an automatic dodge, +4 initiative, +3 strike, parry and dodge, +8 to save vs Horror Factor and +4 roll with punch or impact. At 48 hours it bursts, killing the host, and leaves two new Para-Syms that mature in six months. There is no removing it without the rib cage and organs: radical surgery with a clone or bionic body ready for a brain transplant is the only hope. It ignores other organisms, which mostly die in the burst. Armies have been issued it on the promise of waiting clone or bionic bodies, usually false, or with no warning at all.', 'Rifts World Book 21: Splynn Dimensional Market p.123-124', NULL),
  ('psi-receiver', 'Psi-Receiver (Parasite)', 'rifts', 'magic', NULL, 80000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A mated pair, each about 3 inches (76 mm) long and 1D4 Hit Points, implanted in the brain; kin to the Talo Mind Worms but stronger and more harmful. Only a mortal S.D.C. host with no psionics will do (humans, D-Bees and the like); psychics, Mega-Damage creatures, supernatural beings and creatures of magic are all excluded. Unmated and unhosted they last four months; mated they live two years, and 2D4 young are born about two years into the union. First the host gains Presence Sense and Sixth Sense; 1D4 months on, Telepathy and Empathy; 1D4 months later their range and duration grow 50%; after another 1D4 months they double and Sense Dimensional Anomaly and Sense Time appear. I.S.P. starts at 1D6x10 plus M.E., with 1D4x10 more at the 50% step and again at the doubling. 1D4 weeks after the doubling the powers fire on their own twice a day for their full duration, unbidden and unstoppable; two weeks after that the flood never stops: Presence Sense finds every living thing, Sixth Sense trips at the faintest danger, and he grows paranoid and reclusive, confuses others'' thoughts with his own and acts on them like an advanced schizophrenic, barely sleeps, and is -50% to skills. About half kill themselves within a year. When the parasites die the powers go and the insanities stay. Surgery can remove them at any time but may damage the brain (Surgery Penalty Table for the brain, Rifts Atlantis p.114); Psychic Surgery removes them cleanly. It allows other organisms, but the Brain Feeder kills it once done eating the brain.', 'Rifts World Book 21: Splynn Dimensional Market p.124-125', NULL),
  ('psychic-vapor', 'The Psychic Vapor (Parasite)', 'rifts', 'magic', NULL, 400000, '400,000 credits; super rare', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An astral being hatched from a plain-looking sphere: a pink, smoke-like wisp that drifts into the mouth and nose, chokes the victim briefly until wholly inside, then fills the body without mass. Any mortal host, mortal Mega-Damage beings included; never supernatural beings or creatures of magic. 4D6 Hit Points, hurt only by psionics and magic; up to eight years in a host and ten after; anarchist or miscreant, high animal intelligence. On bonding the host gains Psi-Sword (30 I.S.P.), Psi-Shield (30) and Psychic Body Field (30) plus six physical psionic powers of the player''s or G.M.''s choice, at the strength of a 4th-level Master psionic, saving vs psionics on 10 or more. Base I.S.P. is 1D4x10+20, and he may convert P.P.E. into I.S.P. at two I.S.P. per P.P.E.; I.S.P. returns at 10 an hour, rested or not, and P.P.E. normally. In return it takes one P.P.E. permanently each month; once he has lost 50, or all but one, it leaves as it came, now host-sized fog, sets into a sphere within minutes and floats off to mate, taking 2D6 Hit Points and 2 P.E. of his for good. A mated pair lays 1D6+1 egg spheres once in life, tripled if either drained more than 50 P.P.E. from its host. Only exorcism drives it out. It ignores other organisms.', 'Rifts World Book 21: Splynn Dimensional Market p.125-126', NULL),
  ('spinetwister', 'Spinetwister (Parasite)', 'rifts', 'magic', NULL, 100000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A mated pair, each the size of a large peanut with 3 Hit Points, set on the spine of a mortal host (never M.D.C. D-Bees, supernatural creatures or creatures of magic), that work inward and send tendrils into the major nerves as they breed; one young is born every three months and pushed out through a small hole in the back. Within hours the host is sharper and quicker: +2 P.P., Spd doubled, +5 initiative, +4 strike, +5 parry and dodge, +2 roll with punch or impact. After six months every combat bonus drops by 1, and by 1 more each month after. At one year the pair finish mating and die, the powers and bonuses with them, and their tendrils shrivel tight around the spine: he is left bent and leaning to one side for life, P.S., P.P. and Spd cut by a third and P.B. by 20%. In the first six months surgery or magic removes them with little harm or scarring; after that, removal means rolling on the Surgery Penalty Table (body), Rifts Atlantis p.114, and spinal damage is mended only by Restoration, Bio-Wizard Transmutation, or costly bionic reconstruction or a bionic body. It ignores organisms elsewhere, but one on the spine is attacked 01-50% of the time, surviving if it has more than 10 Hit Points; the attacks recur for 1D4 hours every 1D6 days, during which the host, wracked with spinal pain, is -25% to skills, -2 on every combat bonus and one attack short per melee.', 'Rifts World Book 21: Splynn Dimensional Market p.126', NULL),
  ('temporal-link', 'Temporal Link (Parasite)', 'rifts', 'magic', 25, 5000000, 'Five million credits, sometimes more; expected to fall sharply once the fatal side effect is known', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A smooth round creature about a foot (.3 m) across and 25 lbs (11.25 kg), set in the chest. Any being may host it except gods and alien intelligences. A Mega-Damage creature of 6D6 M.D.C., seemingly of low animal intelligence, never bred in captivity; it lives as long as its host does or until he is taken by the Timestream, and some from the first find have lived for centuries. Two stray temporal warps dropped them on the Splugorth: thousands long ago, archived after research failed, and over two hundred thousand in the last twenty years, now on sale. At first the host automatically sees and senses dimensional anomalies, as the Temporal Magic spells at 4th level, and may save against Temporal Magic that normally only temporal beings can resist; +2 to save vs Temporal Magic. At his next level he gains D-Phase and D-Shift Two Dimensions, castable six times a day in all with no P.P.E. cost; a level later Retro-Viewing and Wink-Out, eight a day; a level after that Time Warp: Age and Time Warp: Slow Motion, ten a day. Three levels on, 4D6 weeks after reaching that third level, he turns into an immaterial ghost and over 1D4 hours fades from existence, no save. Surgery may do lasting harm (Surgery Penalty Table for the body, Rifts Atlantis p.114) and cannot help once the fading starts; taking it out strips the powers and leaves him out of step with time, 1D4x10 minutes early or late for everything, and 1D6 or more times a week, unbidden, about 20 minutes of his activity pass in 1D6 real minutes. It ignores other organisms, which fade with the host. G.M. note: unknown even to the Splugorth, it is tied to a sleeping, unnamed Alien Intelligence akin to the Old Ones, which absorbs the vanished host for an unknown purpose; the parasites may be its creations gathering power or pieces of it.', 'Rifts World Book 21: Splynn Dimensional Market p.126-127', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 11 gear rows are in' AS assertion, count(*) AS got, 11 AS want
  FROM gear WHERE slug IN ('locater', 'lunglock', 'magic-booster', 'mend-and-melt', 'mind-blossom', 'muscle-boots', 'para-sym-transformer', 'psi-receiver', 'psychic-vapor', 'spinetwister', 'temporal-link') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~359-splynn-parasites-b.sql');
